CnB,aAAa;EACb,mBAAmB;EACnB,uBAAuB;EACvB,eAAe;EACf,wCAAwC;EACxC,+BAA+B;EAC/B,YAAY;AACd;;AAEA;EACE,qBAAqB;AACvB;;AAEA;EACE,WAAW;EACX,YAAY;EACZ,+BAA+B;EAC/B,yBAAyB;AAC3B;;AAEA,+BAA+B;AAC/B;EACE,kBAAkB;AACpB;;AAEA;EACE,gBAAgB;AAClB;;AAEA;EACE,kBAAkB;AACpB;;AAEA,8BAA8B;AAC9B;EACE,WAAW;EACX,YAAY;AACd;;AAEA;EACE,WAAW;EACX,YAAY;AACd;;AAEA;EACE,WAAW;EACX,YAAY;AACd;;AAEA,0CAA0C;AAC1C;EACE,UAAU;EACV,WAAW;AACb;;AAEA;EACE,WAAW;EACX,YAAY;AACd;;AAEA;EACE,WAAW;EACX,YAAY;AACd;;AAEA;EACE,kBAAkB;EAClB,WAAW;AACb;;AAEA;EACE,WAAW;EACX,YAAY;EACZ,kBAAkB;EAClB,aAAa;EACb,mBAAmB;EACnB,uBAAuB;EACvB,eAAe;EACf,cAAc;EACd,eAAe;EACf,yCAAyC;EACzC,+BAA+B;AACjC;;AAEA;EACE,qBAAqB;AACvB;;AAEA,sBAAsB;AACtB;EACE,UAAU;AACZ;;AAEA;EACE,mBAAmB;AACrB;;AAEA;EACE,gBAAgB;EAChB,kBAAkB;AACpB;;AAEA;EACE,gBAAgB;AAClB;;;AAGA;EACE,kBAAkB;EAClB,YAAY;EACZ,gBAAgB;EAChB,yBAAyB;AAC3B;;AAEA;EACE,aAAa;EACb,mBAAmB;EACnB,8BAA8B;EAC9B,YAAY;EACZ,aAAa;EACb,qCAAqC;EACrC,kBAAkB;EAClB,qBAAqB;EACrB,eAAe;EACf,eAAe;EACf,YAAY;AACd;;AAEA;EACE,WAAW;EACX,YAAY;EACZ,qBAAqB;EACrB;AACF;;AAEA;EACE,iBAAiB;EACjB,kBAAkB;EAClB,kCAAkC;EAClC,gBAAgB;EAChB,eAAe;EACf,iBAAiB;EACjB,mBAAmB;EACnB,+BAA+B;;;AAGjC;;AAEA;EACE,eAAe;AACjB;;AAEA;EACE,kBAAkB;EAClB,SAAS;EACT,OAAO;EACP,WAAW;EACX,+BAA+B;EAC/B,aAAa;EACb,YAAY;EACZ,kBAAkB;EAClB,0CAA0C;EAC1C,eAAe;EACf,aAAa;EACb,mBAAmB;;AAErB;;AAEA;EACE,aAAa;EACb,uBAAuB;EACvB,uBAAuB;EACvB,iBAAiB;EACjB,sBAAsB;EACtB,mBAAmB;AACrB;;AAEA;EACE,aAAa;EACb,mBAAmB;EACnB,sBAAsB;AACxB;;;AAGA,sBAAsB;AACtB;EACE;IACE,sBAAsB;IACtB,YAAY;EACd;;EAEA;;IAEE,UAAU;IACV,YAAY;EACd;;EAEA;IACE,kBAAkB;EACpB;;EAEA;IACE,kBAAkB;EACpB;AACF;;AAEA,wBAAwB;AACxB;EACE,WAAW;EACX,gBAAgB;EAChB,aAAa;EACb,qCAAqC;EACrC,+BAA+B;EAC/B,kBAAkB;EAClB,cAAc;EACd,eAAe;AACjB;;AAEA;EACE,aAAa;EACb,oCAAoC;AACtC\",\"sourcesContent\":[\".customization-screen {\\r\\n  min-height: 100vh;\\r\\n  width: 800px;\\r\\n  background: rgba(10, 8, 27, 1);\\r\\n  color: #ffffff;\\r\\n  font-family: 'DM Sans', sans-serif;\\r\\n}\\r\\n\\r\\n/* Header */\\r\\n.customization-header {\\r\\n  display: flex;\\r\\n  justify-content: space-between;\\r\\n  align-items: center;\\r\\n  padding: 18px 30px;\\r\\n}\\r\\n\\r\\n.app-name {\\r\\n  font-size: 24px;\\r\\n  font-weight: bold;\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.header-buttons {\\r\\n  display: flex;\\r\\n  gap: 15px;\\r\\n}\\r\\n\\r\\n.back-btn,\\r\\n.next-btn,\\r\\n.publish-btn {\\r\\n  padding: 10px 20px;\\r\\n  border: none;\\r\\n  border-radius: 6px;\\r\\n  cursor: pointer;\\r\\n  font-size: 14px;\\r\\n  font-weight: 500;\\r\\n  transition: all 0.3s ease;\\r\\n  display: flex;\\r\\n  gap: 8px;\\r\\n}\\r\\n\\r\\n.back-btn {\\r\\n  background: rgba(21, 19, 40, 1);\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.next-btn,\\r\\n.publish-btn {\\r\\n  background: rgba(38, 46, 132, 1);\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.next-btn:hover,\\r\\n.publish-btn:hover {\\r\\n  background: #2563eb;\\r\\n}\\r\\n\\r\\n.arrow-left,\\r\\n.arrow-right {\\r\\n  margin: 0 5px;\\r\\n}\\r\\n\\r\\n/* Step Navigation */\\r\\n.step-navigation {\\r\\n  display: flex;\\r\\n  margin: 10px 30px 0px 27px;\\r\\n  padding: 0px;\\r\\n  gap: 60px;\\r\\n  border-bottom: 1px solid #EFEEEC14;\\r\\n  font-weight: 400;\\r\\n}\\r\\n\\r\\n.step {\\r\\n  display: flex;\\r\\n  flex-direction: column;\\r\\n  gap: 4px;\\r\\n  position: relative;\\r\\n  cursor: pointer;\\r\\n  transition: color 0.3s ease;\\r\\n  font-weight: 400;\\r\\n  padding-bottom: 17px;\\r\\n}\\r\\n\\r\\n.step-number {\\r\\n  font-size: 12px;\\r\\n  color: #999;\\r\\n}\\r\\n\\r\\n.step-name {\\r\\n  font-size: 16px;\\r\\n  color: #999;\\r\\n}\\r\\n\\r\\n.step.active .step-number {\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.step.active .step-name {\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.step:not(.active) .step-name {\\r\\n  color: rgba(255, 255, 255, 0.7);\\r\\n}\\r\\n\\r\\n.step.completed .step-number {\\r\\n  color: rgba(43, 110, 47, 1);\\r\\n}\\r\\n\\r\\n.step.completed .step-name {\\r\\n  color: rgba(43, 110, 47, 1);\\r\\n}\\r\\n\\r\\n/* Main Content */\\r\\n.main-content {\\r\\n  display: flex;\\r\\n  height: calc(100vh - 200px);\\r\\n  align-items: flex-start\\r\\n}\\r\\n\\r\\n/* Left Panel */\\r\\n.left-panel {\\r\\n  flex: 1;\\r\\n  background: rgba(29, 26, 49, 0.6);\\r\\n  border-right: 1px solid #333;\\r\\n  overflow-y: auto;\\r\\n  padding: 0;\\r\\n  min-width: 516px;\\r\\n  height: 420px;\\r\\n  border-radius: 12px;\\r\\n  /* margin: 20px; */\\r\\n  margin-right: 10px;\\r\\n  scrollbar-width: thin;\\r\\n  scrollbar-color: #4a4a5d transparent;\\r\\n  scroll-behavior: smooth;\\r\\n  border: 1px solid hsla(249, 92%, 72%, 0.3)\\r\\n}\\r\\n\\r\\n.panel-content {\\r\\n  padding:30px;\\r\\n  max-height: 360px;\\r\\n  overflow-y: auto;\\r\\n\\r\\n}\\r\\n\\r\\n.section {\\r\\n  margin-bottom: 40px;\\r\\n}\\r\\n\\r\\n.section h3 {\\r\\n  color: rgba(140, 121, 255, 1);\\r\\n  font-size: 12px;\\r\\n  font-weight: 400;\\r\\n  margin-bottom: 20px;\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  gap: 5px;\\r\\n}\\r\\n\\r\\n.section h3::after {\\r\\n  content: '';\\r\\n  flex: 1;\\r\\n  height: 1px;\\r\\n  background: rgba(140, 121, 255, 1);\\r\\n}\\r\\n\\r\\n.form-group {\\r\\n  margin-bottom: 25px;\\r\\n}\\r\\n\\r\\n.form-group label {\\r\\n  display: block;\\r\\n  color: rgba(255, 255, 255, 0.6);\\r\\n  font-size: 12px;\\r\\n  margin-bottom: 8px;\\r\\n  font-weight: 500;\\r\\n}\\r\\n\\r\\n.form-group input,\\r\\n.form-group select {\\r\\n  width: 100%;\\r\\n  max-width: 175px;\\r\\n  padding: 12px;\\r\\n  background: rgba(217, 217, 217, 0.02);\\r\\n  border: 1px solid rgb(46 43 69);\\r\\n  border-radius: 6px;\\r\\n  color: #ffffff;\\r\\n  font-size: 12px;\\r\\n  max-height: 4px;\\r\\n  transition: border-color 0.3s ease;\\r\\n}\\r\\n\\r\\n.form-group input:focus,\\r\\n.form-group select:focus {\\r\\n  outline: none;\\r\\n  border-color: #737a86;\\r\\n}\\r\\n\\r\\n.color-input-group {\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  gap: 10px;\\r\\n}\\r\\n\\r\\n.color-input {\\r\\n  flex: 1;\\r\\n}\\r\\n\\r\\n.input-with-settings {\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  gap: 10px;\\r\\n}\\r\\n\\r\\n.input-with-settings input,\\r\\n.input-with-settings select {\\r\\n  flex: 1;\\r\\n}\\r\\n\\r\\n.settings-btn {\\r\\n  width: 35px;\\r\\n  height: 35px;\\r\\n  border-radius: 50%;\\r\\n  background: #3b82f6;\\r\\n  color: #ffffff;\\r\\n  border: none;\\r\\n  cursor: pointer;\\r\\n  font-size: 12px;\\r\\n  font-weight: bold;\\r\\n  transition: background 0.3s ease;\\r\\n}\\r\\n\\r\\n.settings-btn:hover {\\r\\n  background: #2563eb;\\r\\n}\\r\\n\\r\\n/* Custom Dropdown Styles */\\r\\n.custom-select-container {\\r\\n  flex: 1;\\r\\n}\\r\\n\\r\\n.custom-select {\\r\\n  position: relative;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.custom-select .selected {\\r\\n  width: 100%;\\r\\n  max-width: 175px;\\r\\n  padding: 10px;\\r\\n  max-height: 8px;\\r\\n  background: rgba(217, 217, 217, 0.02);\\r\\n  border: 1px solid rgba(46, 43, 69, 1);\\r\\n  border-radius: 3px;\\r\\n  color: rgba(255, 255, 255, 0.6);\\r\\n  font-size: 12px;\\r\\n  cursor: pointer;\\r\\n  display: flex;\\r\\n  justify-content: space-between;\\r\\n  align-items: center;\\r\\n  transition: border-color 0.3s ease;\\r\\n}\\r\\n\\r\\n.custom-select .selected:hover {\\r\\n  border-color: #23334e;\\r\\n}\\r\\n\\r\\n.custom-select.open .selected {\\r\\n  border-color: #23334e;\\r\\n}\\r\\n\\r\\n.dropdown-icon {\\r\\n  color: #ffffff;\\r\\n  transition: transform 0.3s ease;\\r\\n}\\r\\n\\r\\n.custom-select.open .dropdown-icon {\\r\\n  transform: rotate(180deg);\\r\\n}\\r\\n\\r\\n.custom-select .options {\\r\\n  position: absolute;\\r\\n  top: 105%;\\r\\n  left: 0;\\r\\n  right: 0;\\r\\n  background: rgba(50, 44, 90, 0.6);\\r\\n  border: 1px solid rgba(46, 43, 69, 1);\\r\\n  border-top: none;\\r\\n  border-radius: 0 0 6px 6px;\\r\\n  max-height: 120px;\\r\\n  min-width: 195px;\\r\\n  overflow-y: auto;\\r\\n  z-index: 1000;\\r\\n  list-style: none;\\r\\n  margin: 0;\\r\\n  padding: 0;\\r\\n  backdrop-filter: blur(30.7px);\\r\\n}\\r\\n\\r\\n.custom-select .options li {\\r\\n  padding: 12px;\\r\\n  font-size: 12px;\\r\\n  color: #ffffff;\\r\\n  cursor: pointer;\\r\\n  transition: background-color 0.3s ease;\\r\\n  /* border-bottom: 1px solid #333; */\\r\\n}\\r\\n\\r\\n.custom-select .options li:last-child {\\r\\n  border-bottom: none;\\r\\n}\\r\\n\\r\\n.custom-select .options li:hover {\\r\\n  background-color: #342a5e;\\r\\n}\\r\\n\\r\\n/* Interface Grid Layout */\\r\\n.interface-grid {\\r\\n  display: grid;\\r\\n  grid-template-columns: 1fr 1fr;\\r\\n  gap: 20px 55px;\\r\\n  margin-bottom: 30px;\\r\\n}\\r\\n\\r\\n.interface-grid .form-group {\\r\\n  margin-bottom: 0;\\r\\n}\\r\\n\\r\\n/* Trigger Grid Layout */\\r\\n.trigger-grid {\\r\\n  display: grid;\\r\\n  grid-template-columns: 1fr 1fr;\\r\\n  gap: 20px 55px;\\r\\n  margin-bottom: 30px;\\r\\n}\\r\\n\\r\\n.trigger-grid .form-group {\\r\\n  margin-bottom: 0;\\r\\n}\\r\\n\\r\\n.trigger-icon-section {\\r\\n  margin-top: 20px;\\r\\n}\\r\\n\\r\\n.trigger-icon-section h3 {\\r\\n  color: rgba(140, 121, 255, 1);\\r\\n  font-size: 12px;\\r\\n  font-weight: 400;\\r\\n  margin-bottom: 20px;\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  gap: 15px;\\r\\n}\\r\\n\\r\\n.trigger-icon-section h3::after {\\r\\n  content: '';\\r\\n  flex: 1;\\r\\n  height: 1px;\\r\\n  background: rgba(140, 121, 255, 1);\\r\\n}\\r\\n\\r\\n.icon-grid {\\r\\n  display: grid;\\r\\n  grid-template-columns: repeat(8, 1fr);\\r\\n  gap: 10px;\\r\\n  margin-top: 15px;\\r\\n}\\r\\n\\r\\n.icon-option {\\r\\n  width: 40px;\\r\\n  height: 40px;\\r\\n  background: rgba(46, 43, 69, 1);\\r\\n  border: 2px solid rgba(46, 43, 69, 1);\\r\\n  border-radius: 6px;\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  justify-content: center;\\r\\n  cursor: pointer;\\r\\n  transition: all 0.3s ease;\\r\\n}\\r\\n\\r\\n.icon-option:hover {\\r\\n  border-color: #a855f7;\\r\\n}\\r\\n\\r\\n.icon-option.selected {\\r\\n  border: 2px solid rgba(140, 121, 255, 1);\\r\\n}\\r\\n\\r