tion animations */\\r\\n@keyframes slideInRight {\\r\\n  from {\\r\\n    transform: translateX(100%);\\r\\n    opacity: 0;\\r\\n  }\\r\\n  to {\\r\\n    transform: translateX(0);\\r\\n    opacity: 1;\\r\\n  }\\r\\n}\\r\\n\\r\\n/* Header */\\r\\n.payment-header {\\r\\n  display: flex;\\r\\n  justify-content: space-between;\\r\\n  align-items: center;\\r\\n  padding: 18px 30px;\\r\\n}\\r\\n\\r\\n.app-name {\\r\\n  font-size: 24px;\\r\\n  font-weight: bold;\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.header-buttons {\\r\\n  display: flex;\\r\\n  gap: 15px;\\r\\n}\\r\\n\\r\\n.back-btn,\\r\\n.next-btn {\\r\\n  padding: 10px 20px;\\r\\n  border: none;\\r\\n  border-radius: 6px;\\r\\n  cursor: pointer;\\r\\n  font-size: 14px;\\r\\n  font-weight: 500;\\r\\n  transition: all 0.3s ease;\\r\\n  display: flex;\\r\\n  gap: 8px;\\r\\n}\\r\\n\\r\\n.back-btn {\\r\\n  background: rgba(21, 19, 40, 1);\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.back-btn:disabled {\\r\\n  opacity: 0.6;\\r\\n  cursor: not-allowed;\\r\\n}\\r\\n\\r\\n.next-btn {\\r\\n  background: rgba(38, 46, 132, 1);\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.next-btn:hover:not(:disabled) {\\r\\n  background: #2563eb;\\r\\n}\\r\\n\\r\\n.next-btn:disabled {\\r\\n  opacity: 0.6;\\r\\n  cursor: not-allowed;\\r\\n}\\r\\n\\r\\n/* Step Navigation */\\r\\n.step-navigation {\\r\\n  display: flex;\\r\\n  margin: 10px 30px 0px 27px;\\r\\n  padding: 0px;\\r\\n  gap: 100px;\\r\\n  border-bottom: 1px solid #EFEEEC14;\\r\\n  font-weight: 400;\\r\\n}\\r\\n\\r\\n.step {\\r\\n  display: flex;\\r\\n  flex-direction: column;\\r\\n  gap: 4px;\\r\\n  position: relative;\\r\\n  cursor: pointer;\\r\\n  transition: color 0.3s ease;\\r\\n  font-weight: 400;\\r\\n  padding-bottom: 17px;\\r\\n}\\r\\n\\r\\n.step-number {\\r\\n  font-size: 12px;\\r\\n  color: #999;\\r\\n}\\r\\n\\r\\n.step-name {\\r\\n  font-size: 16px;\\r\\n  color: #999;\\r\\n}\\r\\n\\r\\n.step.active .step-number {\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.step.active .step-name {\\r\\n  color: #ffffff;\\r\\n}\\r\\n\\r\\n.step:not(.active) .step-name {\\r\\n  color: rgba(255, 255, 255, 0.7);\\r\\n}\\r\\n\\r\\n.step.completed .step-number {\\r\\n  color: rgba(43, 110, 47, 1);\\r\\n}\\r\\n\\r\\n.step.completed .step-name {\\r\\n  color: rgba(43, 110, 47, 1);\\r\\n}\\r\\n\\r\\n/* Main Content */\\r\\n.payment-screen .main-content {\\r\\n  display: flex;\\r\\n  justify-content: center;\\r\\n  /* align-items: center; */\\r\\n  height: calc(100vh - 200px);\\r\\n  padding: 20px;\\r\\n  text-align: left;\\r\\n  align-items: flex-start\\r\\n}\\r\\n\\r\\n.payment-card {\\r\\n  /* background: linear-gradient(29.71deg, #0B091D 18.17%, #2E2B45 127.91%); */\\r\\n  border-radius: 12px;\\r\\n  border: 1px solid #EFEEEC14;\\r\\n  padding: 40px;\\r\\n  width: 720px;\\r\\n  height: 220px;\\r\\n  position: relative;\\r\\n  overflow: hidden;\\r\\n  opacity: 1;\\r\\n  background: left;\\r\\n  background-size: 800px;\\r\\n  background-repeat: no-repeat;\\r\\n  background-image: url(\\\"../assets/bgpay.png\\\");\\r\\n}\\r\\n\\r\\n.payment-card::before {\\r\\n  content: '';\\r\\n  position: absolute;\\r\\n  top: 0;\\r\\n  left: 0;\\r\\n  right: 0;\\r\\n  bottom: 0;\\r\\n  background: linear-gradient(135deg, rgba(99, 102, 241, 0.1) 0%, rgba(139, 92, 246, 0.1) 100%);\\r\\n  border-radius: 12px;\\r\\n  z-index: -1;\\r\\n}\\r\\n\\r\\n.payment-screen .pricing-flex {\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  justify-content: center;\\r\\n  gap: 40px;\\r\\n  width: 100%;\\r\\n  height: 200px;\\r\\n}\\r\\n\\r\\n.payment-screen .pricing-left {\\r\\n  text-align: center;\\r\\n  flex: 1;\\r\\n  display: flex;\\r\\n  flex-direction: column;\\r\\n  align-items: center;\\r\\n}\\r\\n\\r\\n.main-price {\\r\\n  display: flex;\\r\\n  flex-direction: column;\\r\\n  align-items: center;\\r\\n  margin-bottom: 24px;\\r\\n}\\r\\n\\r\\n.price-number {\\r\\n  font-family: 'Funnel Display', sans-serif;\\r\\n  font-weight: 700;\\r\\n  font-style: bold;\\r\\n  font-size: 66px;\\r\\